parts.openscad_module:
$fn = 96;

bolt_d        = 3.4;
m3_flat_flat  = 5.7;
m3_nut_height = 2.6;
m3_outer_d    = m3_flat_flat / cos(30);
wall_example  = 10;

module m3_nut_trap_host() {
  difference() {
    cube([wall_example, wall_example, wall_example], center = true);
    rotate([0, 0, 30])
      cylinder(h = m3_nut_height + 0.2, d = m3_outer_d, center = true, $fn = 6);
    cylinder(h = wall_example + 2, d = bolt_d, center = true, $fn = 32);
  }
}

m3_nut_trap_host();
